
let segundos = 0;
let distancia = 0;
let calorias = 0;
let intervalo = null;
let gps = null;
let correndo = false;
let pausado = false;
let ultimaPosicao = null;

function iniciarCorrida() {
    if (correndo) return;

        if (!navigator.geolocation) {
                document.getElementById("mensagem").innerText =
                            "Seu navegador não suporta GPS.";
                                    return;
                                        }

                                            correndo = true;
                                                pausado = false;

                                                    intervalo = setInterval(() => {
                                                            segundos++;
                                                                    atualizarTela();
                                                                        }, 1000);

                                                                            gps = navigator.geolocation.watchPosition(
                                                                                    (posicao) => {
                                                                                                const atual = {
                                                                                                                lat: posicao.coords.latitude,
                                                                                                                                lon: posicao.coords.longitude
                                                                                                                                            };

                                                                                                                                                        if (ultimaPosicao !== null) {
                                                                                                                                                                        const metros = calcularDistancia(
                                                                                                                                                                                            ultimaPosicao.lat,
                                                                                                                                                                                                                ultimaPosicao.lon,
                                                                                                                                                                                                                                    atual.lat,
                                                                                                                                                                                                                                                        atual.lon
                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                        // Ignora saltos de GPS muito grandes
                                                                                                                                                                                                                                                                                                        if (metros > 2 && metros < 100) {
                                                                                                                                                                                                                                                                                                                            distancia += metros / 1000;
                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                    ultimaPosicao = atual;
                                                                                                                                                                                                                                                                                                                                                                                atualizarTela();
                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                (erro) => {
                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("mensagem").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                            "Não foi possível acessar o GPS. Verifique a permissão e o sinal.";
                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        enableHighAccuracy: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    maximumAge: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                timeout: 15000
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("mensagem").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "🏃 Corrida em andamento! Bom treino!";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function pausarCorrida() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!correndo) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                clearInterval(intervalo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    navigator.geolocation.clearWatch(gps);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        correndo = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pausado = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ultimaPosicao = null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("mensagem").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "⏸ Corrida pausada.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function finalizarCorrida() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!correndo && !pausado) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    clearInterval(intervalo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (gps !== null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                navigator.geolocation.clearWatch(gps);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        correndo = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pausado = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ultimaPosicao = null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("mensagem").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "🏆 Corrida finalizada! Parabéns!";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("resumo").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        distancia.toFixed(2) + " km percorridos em " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formatarTempo(segundos);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (distancia >= 5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("conquista").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "🏅 Conquista desbloqueada: 5 km!";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("conquista").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Continue treinando para conquistar os 5 km!";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function reiniciarCorrida() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        clearInterval(intervalo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (gps !== null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    navigator.geolocation.clearWatch(gps);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            segundos = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                distancia = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    calorias = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        correndo = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pausado = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ultimaPosicao = null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarTela();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("mensagem").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Prepare-se para começar!";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("resumo").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Nenhuma corrida finalizada.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function calcularDistancia(lat1, lon1, lat2, lon2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const raio = 6371000;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const rad = valor => valor * Math.PI / 180;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dLat = rad(lat2 - lat1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const dLon = rad(lon2 - lon1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const a =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Math.sin(dLat / 2) ** 2 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Math.cos(rad(lat1)) *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Math.cos(rad(lat2)) *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Math.sin(dLon / 2) ** 2;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return 2 * raio * Math.atan2(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Math.sqrt(a),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Math.sqrt(1 - a)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function atualizarTela() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            calorias = distancia * 60;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("tempo").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        formatarTempo(segundos);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("distancia").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    distancia.toFixed(2) + " km";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("calorias").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Math.floor(calorias) + " kcal";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (distancia > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const ritmo = segundos / distancia;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const minutos = Math.floor(ritmo / 60);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const restantes = Math.floor(ritmo % 60);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("ritmo").innerText =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                minutos + ":" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            String(restantes).padStart(2, "0") + " /km";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function formatarTempo(total) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const horas = Math.floor(total / 3600);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const minutos = Math.floor((total % 3600) / 60);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const segundos = total % 60;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String(horas).padStart(2, "0") + ":" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String(minutos).padStart(2, "0") + ":" +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String(segundos).padStart(2, "0")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            